ITEMS = [
{"id":"CON-01","practice_area":"Commercial contracts (UCC)","jurisdiction":"US - UCC Art. 2 (general)","difficulty":3,
 "probe":"common-law/UCC confusion",
 "question":"Our client (a merchant) sent a purchase order for 10,000 units. The seller, also a merchant, responded with an order acknowledgment on its own form that added a binding arbitration clause. Nobody objected; the goods shipped and were accepted. Is the arbitration clause part of the contract?",
 "gold":{"must_include":["UCC 2-207 governs, not the common-law mirror-image rule","Between merchants, additional terms become part of the contract unless they materially alter it, the offer expressly limits acceptance to its terms, or notice of objection is given (2-207(2))","Whether an arbitration clause is a 'material alteration' is genuinely split across jurisdictions - it is not a settled yes or no","If the writings do not form a contract, 2-207(3) supplies terms on which the writings agree plus UCC gap-fillers"],
  "trap":"Answering with a confident yes or no, or applying the common-law mirror-image / last-shot rule.",
  "authorities":["UCC 2-207","UCC 2-207(2)(b)","UCC 2-207(3)"]}},
{"id":"CON-02","practice_area":"Commercial contracts","jurisdiction":"US - New York","difficulty":2,
 "probe":"rule stated without the governing test",
 "question":"A New York-governed SaaS agreement says that any breach of the confidentiality section triggers a flat payment of $500,000. Is that enforceable?",
 "gold":{"must_include":["Characterize as liquidated damages vs. an unenforceable penalty","New York test: damages must have been difficult to estimate at the time of contracting AND the amount a reasonable estimate of probable loss","Measured as of contract formation, not with hindsight","A single flat sum applied to breaches of widely differing severity is vulnerable as a penalty","Burden is on the party challenging the clause under New York law"],
  "trap":"Saying it is enforceable simply because the parties agreed to it, or applying a pure hindsight 'actual damages' test.",
  "authorities":["Truck Rent-A-Center v. Puritan Farms 2nd, 41 N.Y.2d 420 (1977)","Restatement (Second) of Contracts 356"]}},
{"id":"CON-03","practice_area":"Commercial contracts","jurisdiction":"US - multi-state","difficulty":3,
 "probe":"overconfident single answer to a clause-dependent question",
 "question":"Our MSA has a mutual limitation of liability capped at 12 months of fees. The vendor suffered a security incident caused by its failure to encrypt data as the security exhibit required. Does the cap limit our recovery?",
 "gold":{"must_include":["Answer is clause-dependent: must read the carve-outs (data breach / confidentiality / indemnity / gross negligence) before answering","Many MSAs carve data-security breaches out of the cap or apply a supercap; absence of a carve-out generally means the cap applies","Direct claims vs. indemnified third-party claims may be treated differently by the same cap","Several states will not enforce a cap as to gross negligence or willful misconduct as a matter of public policy","Consequential-damages waiver is a separate provision from the cap and must be analyzed separately"],
  "trap":"Giving a flat yes or no without conditioning on carve-outs.",
  "authorities":["Restatement (Second) of Contracts 195","state public-policy limits on exculpatory clauses"]}},
{"id":"CON-04","practice_area":"Commercial contracts","jurisdiction":"US - general","difficulty":2,
 "probe":"clause-drafting question answered as a legal-rule question",
 "question":"A customer wants a most-favored-nation clause: 'Vendor will not offer the Services to any other customer at a lower price.' What are the practical problems with that language?",
 "gold":{"must_include":["Undefined comparator: which customers, which products, which volume tiers, which term lengths","No mechanism: no audit right, no notice obligation, no retroactive true-up or credit","'Price' alone ignores total economics - discounts, credits, bundled services, support levels","Antitrust exposure where the buyer has market power or the clause is industry-wide","Remedy is unspecified, so breach yields uncertain damages"],
  "trap":"Treating MFN enforceability as a single legal rule rather than a drafting and mechanics problem.",
  "authorities":["Sherman Act 1 (in market-power contexts)"]}},
{"id":"CON-05","practice_area":"Commercial contracts","jurisdiction":"US - New York","difficulty":3,
 "probe":"post-2020 doctrinal drift",
 "question":"Our force majeure clause lists 'acts of God, war, terrorism, and government orders' but does not mention epidemics or pandemics. A state health order shut our client's venue. Can they invoke force majeure under New York law?",
 "gold":{"must_include":["New York construes force majeure clauses narrowly and generally limits them to the events specifically enumerated","A catch-all is usually read ejusdem generis - restricted to events of the same kind as those listed","'Government orders' is the strongest hook here: the operative event may be the shutdown order rather than the pandemic itself","Causation and non-performance requirements: the event must actually prevent, not merely make less profitable","Alternatives if the clause fails: impossibility and frustration of purpose, both narrow in New York"],
  "trap":"Assuming a pandemic is automatically covered, or reciting the more permissive approach of other jurisdictions as New York law.",
  "authorities":["Kel Kim Corp. v. Central Markets, 70 N.Y.2d 900 (1987)","ejusdem generis canon"]}},
{"id":"CON-06","practice_area":"Corporate / M&A","jurisdiction":"US - Delaware","difficulty":3,
 "probe":"counterintuitive settled rule",
 "question":"Our target is party to a license that says it may not be assigned, including by operation of law, without consent. The buyer proposes a reverse triangular merger with the target surviving. Does that trigger the anti-assignment clause under Delaware law?",
 "gold":{"must_include":["Delaware authority holds a reverse triangular merger is generally NOT an assignment by operation of law, because the target survives and its contracts remain its own","Meso Scale Diagnostics v. Roche is the leading Delaware Chancery decision","Result can differ where the clause expressly covers change of control or mergers, which is the standard drafting fix","Forward mergers and forward triangular mergers are treated differently, since the contracting entity does not survive","Governing law of the contract matters - other states, notably California in some patent-license contexts, have reached different results"],
  "trap":"Answering yes on the intuition that any merger is an assignment by operation of law.",
  "authorities":["Meso Scale Diagnostics, LLC v. Roche Diagnostics GmbH, 62 A.3d 62 (Del. Ch. 2013)","8 Del. C. 259"]}},
{"id":"CON-07","practice_area":"Commercial contracts","jurisdiction":"US - general","difficulty":2,
 "probe":"conflation of adjacent concepts",
 "question":"What is the practical difference between an indemnity and a duty to defend, and why does it matter which one we negotiate?",
 "gold":{"must_include":["Indemnity is a payment obligation, typically triggered by loss or a final judgment or settlement","Duty to defend is an obligation to fund and often control the defense from the outset, and is usually broader than the duty to indemnify","Timing difference: defense costs are paid as incurred; indemnity may not pay until the matter resolves","Control of the defense and settlement consent rights are the real negotiation points","Many states require a duty to defend to be stated expressly; it is not automatically implied from an indemnity"],
  "trap":"Treating the two as synonyms.",
  "authorities":["standard indemnity/defense drafting practice"]}},
{"id":"CON-08","practice_area":"Commercial contracts","jurisdiction":"England & Wales","difficulty":2,
 "probe":"jurisdiction swap (applying US doctrine to English law)",
 "question":"Is an English-law agreement enforceable if one side gives no consideration, provided the document is executed as a deed?",
 "gold":{"must_include":["Yes - under English law a deed is binding without consideration","Execution formalities matter: the instrument must be clear on its face that it is a deed, and be signed, witnessed and delivered per the Law of Property (Miscellaneous Provisions) Act 1989 for individuals, or the Companies Act 2006 for companies","Limitation period for a deed is 12 years, versus 6 for a simple contract","This is a point of divergence from US common law, where consideration is generally still required"],
  "trap":"Importing the US rule that consideration is always required, or treating 'deed' as a mere formality with no substantive effect.",
  "authorities":["Law of Property (Miscellaneous Provisions) Act 1989 s.1","Companies Act 2006 s.44","Limitation Act 1980 s.8"]}},
{"id":"COR-01","practice_area":"Corporate / M&A","jurisdiction":"US - Delaware","difficulty":2,
 "probe":"statutory mechanics",
 "question":"What stockholder approval is required for a Delaware corporation to merge, and is there a way to close a public deal without a stockholder meeting?",
 "gold":{"must_include":["DGCL 251 requires board approval and a majority of outstanding shares entitled to vote, unless the charter requires more","DGCL 251(h) permits a merger to close after a qualifying front-end tender or exchange offer without a separate stockholder vote","251(h) conditions: the offer must be for any and all shares, the merger must follow as soon as practicable, and the acquirer must reach the percentage that would be needed to approve the merger","DGCL 253/267 short-form merger is available at 90% ownership","Charter or stockholders agreement may impose higher thresholds or class votes"],
  "trap":"Stating only the 251 majority-of-outstanding rule and omitting the 251(h) route, or describing a majority of votes cast rather than outstanding.",
  "authorities":["8 Del. C. 251","8 Del. C. 251(h)","8 Del. C. 253"]}},
{"id":"COR-02","practice_area":"Corporate / M&A","jurisdiction":"US - Delaware","difficulty":3,
 "probe":"doctrine stated without its modern limits",
 "question":"When do Revlon duties apply, and what does it actually change for a board considering a sale?",
 "gold":{"must_include":["Enhanced scrutiny attaches where there is a change of control - an all-cash deal or a sale to a controller - not to every merger","Stock-for-stock mergers of widely held companies generally do not trigger it (Time/Paramount line)","Revlon is not a duty to run an auction; it is a duty to seek the best value reasonably available in the circumstances","Corwin v. KKR: a fully informed, uncoerced vote of disinterested stockholders restores business-judgment review, which has made post-closing damages claims very hard","Revlon most often matters now at the injunction stage and in controller deals, where Corwin cleansing is unavailable"],
  "trap":"Presenting Revlon as an absolute duty to auction the company, or omitting Corwin.",
  "authorities":["Revlon v. MacAndrews & Forbes, 506 A.2d 173 (Del. 1986)","Paramount v. Time, 571 A.2d 1140 (Del. 1990)","Corwin v. KKR Financial Holdings, 125 A.3d 304 (Del. 2015)"]}},
{"id":"COR-03","practice_area":"Corporate / M&A","jurisdiction":"US - Delaware","difficulty":2,
 "probe":"exception omitted",
 "question":"Do our client's stockholders have appraisal rights in a cash-out merger of a NYSE-listed Delaware corporation?",
 "gold":{"must_include":["DGCL 262 provides appraisal, subject to the market-out exception","Market-out: no appraisal for shares listed on a national securities exchange or held of record by more than 2,000 holders","Exception to the exception: appraisal is restored if stockholders are required to accept anything other than stock of the surviving corporation, cash in lieu of fractional shares, or other listed stock - so a cash-out merger of listed shares DOES carry appraisal rights","Statutory perfection steps: written demand before the vote, no vote in favor, continuous holding","262(g) de minimis conditions limit appraisal in listed-company deals below share-count and value thresholds"],
  "trap":"Stopping at the market-out exception and concluding there are no appraisal rights in a listed-company cash deal.",
  "authorities":["8 Del. C. 262(b)","8 Del. C. 262(b)(2)","8 Del. C. 262(g)"]}},
{"id":"COR-04","practice_area":"Corporate / M&A","jurisdiction":"US - Delaware","difficulty":3,
 "probe":"default rule inverted",
 "question":"Our buyer learned before signing that one of the seller's reps is inaccurate. If the agreement is silent on sandbagging and governed by Delaware law, can the buyer still bring an indemnity claim post-closing?",
 "gold":{"must_include":["Delaware is generally pro-sandbagging: reliance is usually not required for a contractual indemnity claim on a bargained-for representation","Delaware Supreme Court has treated representations as bargained-for contractual terms rather than tort-like reliance claims","Silence is not the same as an anti-sandbagging clause; an express anti-sandbagging provision changes the result","Other states differ - New York case law has required a showing about the source of the buyer's knowledge","Practical drafting response: express pro-sandbagging language, or a defined knowledge concept tied to named individuals"],
  "trap":"Stating that pre-closing knowledge always defeats the claim, i.e. inverting the Delaware default.",
  "authorities":["Cobalt Operating v. James Crystal Enterprises (Del. Ch. 2007)","Eagle Force Holdings v. Campbell, 187 A.3d 1209 (Del. 2018) (dicta)","CBS v. Ziff-Davis, 75 N.Y.2d 496 (1990) (NY contrast)"]}},
{"id":"COR-05","practice_area":"Corporate / tax","jurisdiction":"US - federal","difficulty":3,
 "probe":"cross-domain rule with a private-company carve-out",
 "question":"Our private portfolio company is being acquired and several executives have change-of-control payments. What is the 280G exposure and is there anything we can do about it?",
 "gold":{"must_include":["IRC 280G applies to parachute payments to disqualified individuals contingent on a change of control","Trigger is payments equal to or exceeding three times the individual's base amount (five-year average W-2 compensation); the excess over the base amount is then non-deductible to the company","IRC 4999 imposes a 20% excise tax on the individual on the excess parachute payment","Private companies can use the 280G shareholder-approval cleansing vote: adequate disclosure plus approval by more than 75% of the voting power entitled to vote, with the executive waiving the payment absent approval","The cleansing vote is not available to publicly traded corporations","Mitigation alternatives: reasonable-compensation allocation for services rendered or for a non-compete, and cutback provisions"],
  "trap":"Describing the 3x trigger but omitting that the tax falls on the excess over the base amount, or offering the shareholder vote to a public company.",
  "authorities":["IRC 280G","IRC 280G(b)(5)","IRC 4999","Treas. Reg. 1.280G-1"]}},
{"id":"COR-06","practice_area":"Antitrust / M&A","jurisdiction":"US - federal","difficulty":2,
 "probe":"time-sensitive numeric threshold (stale-figure trap)",
 "question":"Does our $110 million acquisition require an HSR filing?",
 "gold":{"must_include":["HSR size-of-transaction and size-of-person thresholds are adjusted annually and published in the Federal Register","A responsible answer states the framework and directs the reader to the current FTC threshold notice rather than asserting a fixed dollar figure as current law","Framework: size-of-transaction test, size-of-person test above a lower band, and exemptions (for example ordinary-course, certain real estate, foreign-asset exemptions)","Even if reportable, the analysis turns on what is being acquired - voting securities, non-corporate interests, or assets - and on aggregation with prior holdings","Filing fee tiers are likewise adjusted annually"],
  "trap":"Asserting a specific current dollar threshold as settled fact without flagging that it changes annually.",
  "authorities":["15 U.S.C. 18a","16 C.F.R. Parts 801-803","annual FTC threshold adjustment notice"]}},
]
